SELECT p.code, c.name_th, c.name_en, p.credits FROM plan_item p LEFT JOIN course c ON c.code = p.code WHERE p.year = 1 AND p.semester = 1 AND NOT EXISTS (SELECT 1 FROM plan_slot t JOIN plan_slot_member m ON m.slot_id = t.id WHERE t.program_id = p.program_id AND t.year = p.year AND t.semester = p.semester AND m.code = p.code) ORDER BY p.id;
SELECT credits, n_entries FROM main.v_semester_credits_full WHERE year = 1 AND semester = 1;
SELECT id, kind, name_th AS slot, code AS code_pattern, credits FROM plan_slot WHERE year = 1 AND semester = 1 ORDER BY id

SELECT p.code, c.name_th, c.name_en, p.credits FROM plan_item p LEFT JOIN course c ON c.code = p.code WHERE p.year = 4 AND p.semester = 1 AND NOT EXISTS (SELECT 1 FROM plan_slot t JOIN plan_slot_member m ON m.slot_id = t.id WHERE t.program_id = p.program_id AND t.year = p.year AND t.semester = p.semester AND m.code = p.code) ORDER BY p.id;
SELECT credits, n_entries FROM main.v_semester_credits_full WHERE year = 4 AND semester = 1;
SELECT id, kind, name_th AS slot, code AS code_pattern, credits FROM plan_slot WHERE year = 4 AND semester = 1 ORDER BY id;
SELECT m.group_no, m.group_name, m.code, c.name_th, c.name_en, c.credits FROM plan_slot_member m LEFT JOIN course c ON c.code = m.code WHERE m.slot_id = 5 ORDER BY m.group_no, m.code;
SELECT m.group_no, m.group_name, m.code, c.name_th, c.name_en, c.credits FROM plan_slot_member m LEFT JOIN course c ON c.code = m.code WHERE m.slot_id = 6 ORDER BY m.group_no, m.code;
